def maxWidthRamp(nums: list[int]) -> int:
    stack = []
    for i, n in enumerate(nums):
        if not stack or nums[stack[-1]] > n:
            stack.append(i)
    res = 0
    for j in range(len(nums) - 1, -1, -1):
        while stack and nums[stack[-1]] <= nums[j]:
            res = max(res, j - stack.pop())
    return res

